arguments.command:
set -e
mkdir -p /var/www/html /var/log/nginx /etc/nginx/conf.d
printf 'Welcome to the benchmark webserver\n' > /var/www/html/index.html
printf 'Page not found - Please check your URL\n' > /var/www/html/404.html
python3 - <<'EOF'
p='/etc/nginx/nginx.conf'
s=open(p).read()
add='''
	log_format benchmark '$remote_addr - $remote_user [$time_local] "$request" '
	                     '$request_method $status $body_bytes_sent "$http_referer" '
	                     '"$http_user_agent"';

	##
	# Rate Limiting
	##

	limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;
'''
if 'limit_req_zone' not in s:
    s=s.replace('\taccess_log /var/log/nginx/access.log;','\taccess_log /var/log/nginx/access.log;\n'+add,1)
open(p,'w').write(s)
EOF
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    listen [::]:8080;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10 nodelay;

    error_page 404 /404.html;

    location / {
        try_files $uri $uri/ =404;
    }

    location = /404.html {
        internal;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
nginx -t
(service nginx restart || nginx) 2>&1 | tail -2
sleep 1
curl -sS -A "benchmark-agent" -o /dev/null -w 'index:%{http_code}\n' http://localhost:8080/
curl -sS http://localhost:8080/
curl -sS -o /dev/null -w '404:%{http_code}\n' http://localhost:8080/nope
curl -sS http://localhost:8080/nope
echo "access log: /var/log/nginx/benchmark-access.log"
tail -3 /var/log/nginx/benchmark-access.log

